describe('Notification Filtering by Type', () => {
  beforeEach(() => {
    cy.visit('/notifications');
  });

  it('should filter notifications by type and display only selected notifications', () => {
    // Setup: Add multiple notifications of different types
    cy.get('[data-testid="add-notification-button"]').click();
    cy.get('[data-testid="notification-form"]').within(() => {
      cy.get('[data-testid="notification-type-info"]').click();
      cy.get('[data-testid="notification-title-test"]').type('Test Info');
      cy.get('[data-testid="notification-body-test"]').type('This is an informational notification');
      cy.get('[data-testid="notification-send-button"]').click();
    });

    cy.get('[data-testid="add-notification-button"]').click();
    cy.get('[data-testid="notification-form"]').within(() => {
      cy.get('[data-testid="notification-type-warning"]').click();
      cy.get('[data-testid="notification-title-test"]').type('Test Warning');
      cy.get('[data-testid="notification-body-test"]').type('This is a warning notification');
      cy.get('[data-testid="notification-send-button"]').click();
    });

    cy.get('[data-testid="add-notification-button"]').click();
    cy.get('[data-testid="notification-form"]').within(() => {
      cy.get('[data-testid="notification-type-error"]').click();
      cy.get('[data-testid="notification-title-test"]').type('Test Error');
      cy.get('[data-testid="notification-body-test"]').type('This is an error notification');
      cy.get('[data-testid="notification-send-button"]').click();
    });

    // Verify notifications are displayed
    cy.get('[data-testid="notification-list"]').should('be.visible');
    cy.get('[data-testid="notification-item"]').should('have.length.greaterThan', 0);

    // Filter by type
    cy.get('[data-testid="filter-button"]').click();
    cy.get('[data-testid="filter-type-info"]').click();

    // Verify only info notifications are displayed
    cy.get('[data-testid="notification-item"]').should('have.length.equal', 1);
    cy.get('[data-testid="notification-item"]').first().should('contain', 'Test Info');

    // Verify warning notifications are not displayed
    cy.get('[data-testid="notification-item"]').should('not.contain', 'Test Warning');

    // Filter by type again
    cy.get('[data-testid="filter-button"]').click();
    cy.get('[data-testid="filter-type-error"]').click();

    // Verify only error notifications are displayed
    cy.get('[data-testid="notification-item"]').should('have.length.equal', 1);
    cy.get('[data-testid="notification-item"]').first().should('contain', 'Test Error');

    // Verify info and warning notifications are not displayed
    cy.get('[data-testid="notification-item"]').should('not.have.length.greaterThan', 1);
  });

  it('should handle empty notification list after filtering', () => {
    // Setup: Add multiple notifications
    cy.get('[data-testid="add-notification-button"]').click();
    cy.get('[data-testid="notification-form"]').within(() => {
      cy.get('[data-testid="notification-type-info"]').click();
      cy.get('[data-testid="notification-title-test"]').type('Test Info');
      cy.get('[data-testid="notification-body-test"]').type('This is an informational notification');
      cy.get('[data-testid="notification-send-button"]').click();
    });

    cy.get('[data-testid="add-notification-button"]').click();
    cy.get('[data-testid="notification-form"]').within(() => {
      cy.get('[data-testid="notification-type-warning"]').click();
      cy.get('[data-testid="notification-title-test"]').type('Test Warning');
      cy.get('[data-testid="notification-body-test"]').type('This is a warning notification');
      cy.get('[data-testid="notification-send-button"]').click();
    });

    // Filter by type
    cy.get('[data-testid="filter-button"]').click();
    cy.get('[data-testid="filter-type-error"]').click();

    // Verify no notifications are displayed
    cy.get('[data-testid="notification-list"]').should('be.visible');
    cy.get('[data-testid="notification-item"]').should('not.exist');

    // Verify empty state message is displayed
    cy.get('[data-testid="empty-notifications-message"]').should('be.visible');
    cy.get('[data-testid="empty-notifications-message"]').should('contain', 'No notifications found');
  });
});
